   226	function decision(offer: Offer, settings: NextSettings): Offer["presets"][number] | null {
   227	  if (settings.stop) return null;
   228	  const list = offer.presets.find((p) => p.kind === "checklist");
   229	  if (list) return list;
   230	  return offer.presets.find((p) => p.kind === "declareSubject" && (p.suggestions?.[0] ?? "") !== "") ?? null;
   231	}
