   233	/** What one press of the follow key sends, or nothing for it to send. */
   234	export function nextPress(
   235	  state: DeckState,
   236	  settings: NextSettings,
   237	): { press: "primary" } | { press: "answer"; answer: Record<string, string> } | null {
   238	  const offer = state.snapshot?.offer;
   239	  if (!offer) return null;
   240	  if (offer.primary) return { press: "primary" };
