   290	export function setupFace(state: DeckState, setup?: { id: string; title: string }): Face {
   291	  const c = common(state) ?? flashed(state);
   292	  if (c) return c;
   293	  if (!setup) return { title: "Set up", tone: "dim" };
   294	  const offer = state.snapshot?.offer;
   295	  if (!offer) return { title: "Loading…", tone: "dim" };
