   297	  return (offer.setups ?? []).some((s) => s.id === setup.id)
   298	    ? { title: setup.title, tone: "live", when: "Apply setup" }
   299	    : { title: setup.title, tone: "dim", when: "Not here" };
   300	}
   301	
   302	export function undoFace(state: DeckState): Face {
   303	  const c = common(state) ?? flashed(state);
   304	  if (c) return c;
   305	  const undo = state.snapshot?.offer?.undo;
   306	  // The key says "Undo" either way: what it would take back is the run's
   307	  // business, and a key too small to read it is no help at the table.
   308	  return undo ? { title: "Undo", tone: "live" } : { title: "Undo", tone: "dim" };
   309	}
