   326	  return `${Math.floor(s / 60)}:${String(s % 60).padStart(2, "0")}`;
   327	}
   328	
   329	export function metricFace(state: DeckState, field: MetricField, now: number): Face {
   330	  const c = common(state);
   331	  if (c) return c;
   332	  const snap = state.snapshot;
   333	  if (!snap) return { title: "Loading…", tone: "dim" };
   334	  if (field === "score") return { title: snap.score?.text ?? "—", tone: "live", when: "Score" };
   335	  if (field === "unit") return { title: String(snap.unit ?? "—"), tone: "live", when: snap.words?.unit ?? "Unit" };
   336	  if (field === "latest") return { title: snap.latest?.text ?? "—", tone: "live" };
   337	  if (field === "leader") {
   338	    const top = snap.standings?.[0];
   339	    return top ? { title: top.name, tone: "live", when: `${top.points} pts` } : { title: "—", tone: "dim", when: "Leader" };
   340	  }
   341	  if (field === "clock") {
   342	    const clock = snap.clocks?.find((x) => x.status === "running") ?? snap.clocks?.[0];
   343	    if (!clock || !snap.at) return { title: "—", tone: "dim", when: "Clock" };
   344	    const running = clock.kind === "timer" && clock.status === "running" && clock.seconds !== null;
   345	    const fraction = running ? clockElapsedMs(clock, snap.at, now) / (clock.seconds! * 1000) : undefined;
   346	    return { title: clockText(clock, snap.at, now), tone: "live", when: clock.label, ...(fraction !== undefined ? { fraction } : {}) };
   347	  }
   348	  if ("counter" in field) {
   349	    const x = snap.counters?.find((k) => k.id === field.counter);
   350	    return x ? { title: String(x.value), tone: "live", when: x.label } : { title: "—", tone: "dim" };
   351	  }
   352	  const r = snap.resources?.find((k) => k.id === field.resource);
   353	  return r ? { title: r.max === null ? String(r.value) : `${r.value}/${r.max}`, tone: "live", when: r.label } : { title: "—", tone: "dim" };
   354	}
