     1	import { initial, reduce, type DeckEvent, type DeckState } from "./state.ts";
     2	
     3	export interface Store {
     4	  state: DeckState;
     5	  dispatch(e: DeckEvent): void;
     6	  subscribe(l: (s: DeckState) => void): () => void;
     7	}
     8	
     9	/** The one live state, and the actions that redraw when it moves. */
    10	export function makeStore(now: () => number = Date.now): Store {
    11	  const listeners = new Set<(s: DeckState) => void>();
    12	  const store: Store = {
    13	    state: initial(),
    14	    dispatch(e) {
    15	      const next = reduce(store.state, e, now());
    16	      if (next === store.state) return;
    17	      store.state = next;
    18	      for (const l of listeners) l(next);
    19	    },
    20	    subscribe(l) {
    21	      listeners.add(l);
    22	      return () => listeners.delete(l);
    23	    },
    24	  };
    25	  return store;
    26	}

