     1	import { configDir, deviceFlow, forgetSession, needsRenewal, readSession, renew, writeSession, type Session } from "@runlog/session";
     2	
     3	export interface Account {
     4	  apiBase: string;
     5	}
     6	
     7	/**
     8	 * The address without its trailing slash.
     9	 *
    10	 * Every caller joins a path onto it, and a streamer who pastes the address
    11	 * out of a browser bar brings the slash with them - which would ask for
    12	 * `//api/...` and dial `//ws`. Trimmed wherever the base is used, rather
    13	 * than trusted to have been cleaned on the way in.
    14	 */
    15	export function normalizeBase(apiBase: string): string {
    16	  return apiBase.trim().replace(/\/+$/, "");
    17	}
    18	
    19	/**
    20	 * The deck's session, kept in a file of the plugin's own.
    21	 *
    22	 * Not in Stream Deck's global settings: those are handed to the property
    23	 * inspector, which is a web view, and a refresh token is the one thing
    24	 * this plugin holds that must never be. The CLI keeps its session the
    25	 * same way, in the same directory tree, under a different name.
    26	 */
    27	export function sessionDir(): string {
    28	  return configDir("runlog-deck");
    29	}
    30	
    31	// A test's own directory, so a test run never renews the real rotating
    32	// token and never collides with the CLI's. Unset outside of tests.
    33	let dirOverride: string | null = null;
    34	export function __setSessionDirForTests(dir: string | null): void {
    35	  dirOverride = dir;
    36	}
    37	function dir(): string {
    38	  return dirOverride ?? sessionDir();
    39	}
    40	
    41	export function loadSession(): Session | null {
    42	  return readSession(dir());
    43	}
    44	
    45	export function signOut(): void {
    46	  forgetSession(dir());
    47	}
    48	
    49	async function clientOf(account: Account): Promise<{ clientId: string; issuer: string }> {
    50	  const res = await fetch(`${normalizeBase(account.apiBase)}/api/auth/deck`);
    51	  const body = (await res.json()) as { clientId?: string | null; issuer?: string };
    52	  if (!body.clientId) throw new Error("this copy of Runlog has no sign-in for a deck");
    53	  return { clientId: body.clientId, issuer: body.issuer ?? "https://api.workos.com" };
    54	}
    55	
    56	export async function signIn(account: Account, say: (line: string) => void, open: (url: string) => void): Promise<Session> {
    57	  const { clientId, issuer } = await clientOf(account);
    58	  const session = await deviceFlow(clientId, issuer, {
    59	    fetch: (input, init) => fetch(input, init),
    60	    sleep: (ms) => new Promise((r) => setTimeout(r, ms)),
    61	    say,
    62	    open,
    63	    now: () => Date.now(),
    64	  });
    65	  writeSession(dir(), session);
    66	  return session;
    67	}
    68	
    69	/** The bearer to send, renewed first when it is about to lapse; null means sign in. */
    70	export async function bearer(_account: Account): Promise<string | null> {
    71	  const session = loadSession();
    72	  if (!session) return null;
    73	  if (!needsRenewal(session, Date.now())) return session.accessToken;
    74	  try {
    75	    const renewed = await renew(session);
    76	    writeSession(dir(), renewed);
    77	    return renewed.accessToken;
    78	  } catch {
    79	    // A refresh the issuer refused is a session that is over. Leave the
    80	    // file so a retry after a network blip is not a full sign-in, and
    81	    // let the caller read the null as "Sign in again".
    82	    return null;
    83	  }
    84	}

