  const base =
    process.env["RUNLOG_CONFIG_DIR"] ??
    (process.platform === "win32"
      ? join(process.env["APPDATA"] ?? join(homedir(), "AppData", "Roaming"), "runlog")
      : join(process.env["XDG_CONFIG_HOME"] ?? join(homedir(), ".config"), "runlog"));
  return base;
}

