     1	import { action, type KeyDownEvent } from "@elgato/streamdeck";
     2	
     3	import { store, turnOff, turnOn } from "../plugin.ts";
     4	import { connectFace, type DeckState, type Face } from "../state.ts";
     5	import { RunlogAction } from "./base.ts";
     6	
     7	/**
     8	 * The switch the whole plugin hangs off.
     9	 *
    10	 * A Stream Deck is never off, so a socket held whenever the plugin was
    11	 * configured would be a socket held around the clock for nothing. This is
    12	 * the state the streamer enters instead: nothing is open until it is
    13	 * pressed, and pressing it again closes everything.
    14	 */
    15	@action({ UUID: "com.scrthq.runlog.connect" })
    16	export class Connect extends RunlogAction {
    17	  face(state: DeckState): Face {
    18	    return connectFace(state);
    19	  }
    20	
    21	  override async onKeyDown(ev: KeyDownEvent): Promise<void> {
    22	    if (store.state.session === "none") {
    23	      // Nothing to connect to yet; the face already says to sign in.
    24	      await ev.action.showAlert();
    25	      return;
    26	    }
    27	    if (store.state.on) turnOff();
    28	    else turnOn();
    29	  }
    30	}
