     1	import streamDeck, { action, type KeyDownEvent } from "@elgato/streamdeck";
     2	
     3	import { store } from "../plugin.ts";
     4	import { pressFace, type DeckState, type Face, type PressTarget } from "../state.ts";
     5	import { RunlogAction } from "./base.ts";
     6	
     7	export type PressSettings = { target?: PressTarget };
     8	
     9	/** One move, the waiting roll, or a preset answer - whichever the key was set to. */
    10	@action({ UUID: "com.scrthq.runlog.press" })
    11	export class Press extends RunlogAction<PressSettings> {
    12	  face(state: DeckState, settings: PressSettings): Face {
    13	    return settings.target ? pressFace(state, settings.target) : { title: "Set up", tone: "dim" };
    14	  }
    15	
    16	  override async onKeyDown(ev: KeyDownEvent<PressSettings>): Promise<void> {
    17	    const target = ev.payload.settings.target;
    18	    if (!target) {
    19	      await ev.action.showAlert();
    20	      return;
    21	    }
    22	    if (target.kind === "roll") await this.send(ev.action, { press: "primary" });
    23	    else if (target.kind === "move") await this.send(ev.action, { press: "move", move: target.id });
    24	    // The two presets answer in the page's own words: a subject is the
    25	    // typed value, and a list is ticked whole - `takePress` takes
    26	    // `{ ticks: "all" }` and nothing else for it.
    27	    else if (target.preset === "checklist") await this.send(ev.action, { press: "answer", answer: { ticks: "all" } });
    28	    else await this.send(ev.action, { press: "answer", answer: { subject: target.value } });
    29	  }
    30	
    31	  /** The inspector cannot know the pack's own words, so the run's offer is handed to it. */
    32	  override async onPropertyInspectorDidAppear(): Promise<void> {
    33	    await super.onPropertyInspectorDidAppear();
    34	    const offer = store.state.snapshot?.offer;
    35	    await streamDeck.ui.sendToPropertyInspector({ t: "offer", moves: offer?.moves ?? [], presets: offer?.presets ?? [] });
    36	  }
    37	}
