     1	import streamDeck, { action, type KeyDownEvent } from "@elgato/streamdeck";
     2	
     3	import { store } from "../plugin.ts";
     4	import { runFace, type DeckState, type Face, type HeldRun } from "../state.ts";
     5	import { RunlogAction } from "./base.ts";
     6	
     7	/** Which held run pressing Run would move to next, wrapping past the last. */
     8	export function nextPin(runs: Array<Pick<HeldRun, "id">>, pinned: string | null): string | null {
     9	  if (runs.length === 0) return null;
    10	  const i = runs.findIndex((r) => r.id === pinned);
    11	  return runs[(i + 1) % runs.length]!.id;
    12	}
    13	
    14	/**
    15	 * Which run the deck is on.
    16	 *
    17	 * Press to cycle through the held runs and pin the next one; the
    18	 * inspector is the authoritative picker with full names. Pinning beats
    19	 * following, permanently: a pinned run that ends says so rather than
    20	 * drifting to whichever run moved last.
    21	 */
    22	@action({ UUID: "com.scrthq.runlog.run" })
    23	export class Run extends RunlogAction {
    24	  face(state: DeckState): Face {
    25	    return runFace(state);
    26	  }
    27	
    28	  override async onKeyDown(ev: KeyDownEvent): Promise<void> {
    29	    const id = nextPin(store.state.runs, store.state.pinned);
    30	    if (!id) {
    31	      await ev.action.showAlert();
    32	      return;
    33	    }
    34	    await pin(id);
    35	    await ev.action.showOk();
    36	  }
    37	
    38	  /** The picker needs the full list, named; the key face only ever shows the one attached. */
    39	  override async onPropertyInspectorDidAppear(): Promise<void> {
    40	    await super.onPropertyInspectorDidAppear();
    41	    await streamDeck.ui.sendToPropertyInspector({ t: "runs", runs: runsForInspector(store.state.runs), pinned: store.state.pinned });
    42	  }
    43	}
    44	
    45	/** Pins a run, or - with `null` - unpins, so the deck follows again. */
    46	export async function pin(id: string | null): Promise<void> {
    47	  await streamDeck.settings.setGlobalSettings({ ...(await streamDeck.settings.getGlobalSettings()), pinned: id });
    48	  store.dispatch({ t: "pin", id });
    49	}
    50	
    51	/**
    52	 * The held runs, as plain objects.
