     1	import type { Step } from "@runlog/rules-schema";
     2	import { checklistOf, closesUnit } from "@runlog/engine";
     3	import { pointOf } from "./evidence.ts";
     4	
     5	/**
     6	 * What a deck may press, right now, in the pack's own words.
     7	 *
     8	 * The same reasoning as `snapshot.asks`: only a device holding the pack
     9	 * and the log can say what is on offer, so it is published rather than
    10	 * worked out by the server. Wider than `asks`, because a deck is the
    11	 * owner pressing and may do what the page's own buttons do.
    12	 *
    13	 * Deliberately conservative, for the reason `handsFree.ts` gives: this
    14	 * removes ceremony, never a decision. Anything the player is genuinely
    15	 * being asked, anything owed, and anything typed stops here and says so.
    16	 */
    17	export interface Offer {
    18	  seq: number;
    19	  primary: { id: "roll" | "carry-on" | "close" | "enter"; label: string; kind: string } | null;
    20	  moves: Array<{ id: string; label: string }>;
    21	  undo: { what: string } | null;
    22	  /** Why a deck cannot press this, in words a key face can carry. */
    23	  needsPage: string | null;
    24	  presets: Array<{ kind: string; label: string; suggestions?: string[]; items?: number }>;
    25	}
    26	
    27	export interface OfferInput {
    28	  /** The snapshot this offer belongs to; a press carries it back. */
    29	  seq: number;
    30	  /** Active, editable, and actually started. */
    31	  live: boolean;
    32	  /** Nothing more is being asked of this step. */
    33	  settled: boolean;
    34	  step: Step | null;
    35	  stepLabel: string | null;
    36	  moves: Array<{ id: string; label: string }>;
    37	  canUndo: boolean;
    38	  lastResult: string | null;
    39	  /** Obligations standing in the way. */
    40	  owed: number;
    41	  /** What the run would suggest for a subject, where it suggests anything. */
    42	  suggestions: string[];
    43	  /** What the page's between-units button says, or null when the run is not between units. */
    44	  between: string | null;
    45	  /**
    46	   * What the step's own button says once every box is ticked, or null
    47	   * where the step has no list. The preset presses that button, so it is
    48	   * offered in the words the page uses for it.
    49	   */
    50	  finishLabel: string | null;
    51	}
    52	
    53	/**
    54	 * Steps a key can answer with one press, because they ask nothing first.
    55	 *
    56	 * A step that closes the unit is not listed here: it is routed by
    57	 * `closesUnit` below, the same way whichever kind it is, rather than by
    58	 * its own kind.
    59	 */
    60	const PRESSABLE: Record<string, "roll" | "carry-on" | "close" | "enter"> = {
    61	  rollTable: "roll",
    62	};
    63	
    64	/** Steps that take something typed, and the preset that covers each. */
    65	const TYPED = new Set(["declareSubject"]);
    66	
    67	export function offerOf(input: OfferInput): Offer {
    68	  const moves = input.moves;
    69	  const undo = input.canUndo && input.lastResult ? { what: input.lastResult } : null;
    70	  const bare = { seq: input.seq, moves, undo, presets: [] as Offer["presets"] };
    71	
    72	  // A run nobody is playing -- not started, read-only, ended -- offers
    73	  // nothing at all, moves and undo included. They used to ride out on
    74	  // `bare`, and `takePress` reads only those two fields when it takes a
    75	  // move or an undo, so a deck could move a run the page itself would not
    76	  // let anyone touch.
    77	  if (!input.live) return { ...bare, moves: [], undo: null, primary: null, needsPage: "Open the run on the page" };
    78	  if (!input.step) {
    79	    if (input.between) return { ...bare, primary: { id: "enter", label: input.between, kind: "between" }, needsPage: null };
    80	    return { ...bare, primary: null, needsPage: null };
    81	  }
    82	
    83	  const step = input.step;
    84	  const kind = step.kind;
    85	  const label = input.stepLabel ?? "";
    86	
    87	  // An unsettled step is still being asked something, the same reasoning
    88	  // `closesTheUnit` uses to refuse an unsettled unit: it is not yet a bare
    89	  // press for a key to make.
    90	  if (!input.settled) return { ...bare, primary: null, needsPage: `${label} on the page` };
=== takePress.ts ===
     1	import type { Offer } from "./offer.ts";
     2	
     3	export interface Press {
     4	  from: string;
     5	  run: string;
     6	  seq: number;
     7	  ref: string;
     8	  press: string;
     9	  move?: string;
    10	  answer?: Record<string, unknown>;
    11	}
    12	
    13	export interface Verdict {
    14	  ok: boolean;
    15	  say?: string;
    16	}
    17	
    18	export interface Acts {
    19	  primary: () => void;
    20	  move: (id: string) => void;
    21	  undo: () => void;
    22	  answer: (answer: Record<string, unknown>) => void;
    23	}
    24	
    25	/**
    26	 * Whether a press from outside may be taken, and taking it.
    27	 *
    28	 * Given everything it decides on, because this is the one place a run
    29	 * can be moved by something that is not looking at it. Two rules do the
    30	 * work. A press names the offer it was drawn from, so one made while
    31	 * the unit was closing cannot roll into the next unit. And a press
    32	 * names itself and who sent it, so two decks racing for the same button
    33	 * each move it once, and one deck retried after an answer that never
    34	 * arrived moves it only once.
    35	 *
    36	 * Not total, though: an `act` may throw, most likely a write raced by
    37	 * another device. That still spends the ref and settles a verdict --
    38	 * the deck is told the press failed rather than left waiting on one
    39	 * that will never answer.
    40	 */
    41	export function takePress(press: Press, at: { seq: number; offer: Offer; seen: Map<string, Verdict> }, act: Acts): Verdict {
    42	  const key = `${press.from}:${press.ref}`;
    43	  const already = at.seen.get(key);
    44	  if (already) return already;
    45	
    46	  const settle = (verdict: Verdict): Verdict => {
    47	    at.seen.set(key, verdict);
