=========== streamdeck/com.scrthq.runlog.sdPlugin/ui/account.js ===========
     1	/**
     2	 * The account block every inspector carries: the address, sign in, sign out,
     3	 * reconnect, and the device flow's code while one is running.
     4	 *
     5	 * A script rather than an HTML fragment because a property inspector page is
     6	 * loaded straight from disk with no build step and no include - so the block
     7	 * has one home here and each page is one line.
     8	 *
     9	 * Drop `<div id="runlog-account"></div>` on the page, then load this after
    10	 * sdpi-components.js.
    11	 */
    12	(() => {
    13	  const mount = document.getElementById("runlog-account");
    14	  if (!mount) return;
    15	  const { streamDeckClient } = SDPIComponents;
    16	
    17	  mount.innerHTML = `
    18	    <sdpi-item label="Runlog address">
    19	      <sdpi-textfield setting="apiBase" global placeholder="https://runlog.scrthq.com"></sdpi-textfield>
    20	    </sdpi-item>
    21	    <sdpi-item label="Account">
    22	      <sdpi-button id="runlog-signin">Sign in</sdpi-button>
    23	      <sdpi-button id="runlog-signout">Sign out</sdpi-button>
    24	      <sdpi-button id="runlog-reconnect">Reconnect</sdpi-button>
    25	    </sdpi-item>
    26	    <sdpi-item label="Status"><span id="runlog-who">Loading…</span></sdpi-item>
    27	    <div id="runlog-code-row" style="display: none">
    28	      <sdpi-item label="Your code">
    29	        <strong id="runlog-code"></strong>
    30	        <a id="runlog-link" target="_blank" rel="noreferrer">Open the sign-in page</a>
    31	      </sdpi-item>
    32	    </div>`;
    33	
    34	  const el = (id) => document.getElementById(id);
    35	  const send = (payload) => streamDeckClient.send("sendToPlugin", payload);
    36	
    37	  el("runlog-signin").addEventListener("click", () => {
    38	    el("runlog-who").textContent = "Signing in…";
    39	    send({ t: "signin" });
    40	  });
    41	  el("runlog-signout").addEventListener("click", () => send({ t: "signout" }));
    42	  el("runlog-reconnect").addEventListener("click", () => send({ t: "reconnect" }));
    43	
    44	  streamDeckClient.sendToPropertyInspector.subscribe(({ payload }) => {
    45	    if (!payload) return;
    46	    if (payload.t === "code") {
    47	      el("runlog-code-row").style.display = "";
    48	      el("runlog-code").textContent = payload.code;
    49	      // The link comes off a socket; only an http(s) one is worth opening.
    50	      el("runlog-link").href = /^https?:\/\//.test(payload.url ?? "") ? payload.url : "";
    51	    }
    52	    if (payload.t === "who") {
    53	      el("runlog-code-row").style.display = "none";
    54	      const signedIn = payload.signedIn ? "Signed in" : "Not signed in";
    55	      // A sign-in that failed says why, and keeps saying it until the next
    56	      // time the plugin reports who is signed in.
    57	      el("runlog-who").textContent = payload.error ? `${signedIn} — ${payload.error}` : signedIn;
    58	    }
    59	  });
    60	})();
=========== streamdeck/com.scrthq.runlog.sdPlugin/ui/press.html ===========
     1	<!doctype html>
     2	<html>
     3	  <head lang="en">
     4	    <title>Press Settings</title>
     5	    <meta charset="utf-8" />
     6	    <script src="https://sdpi-components.dev/releases/v4/sdpi-components.js"></script>
     7	  </head>
     8	
     9	  <body>
    10	    <sdpi-item label="Press">
    11	      <select id="target"></select>
    12	    </sdpi-item>
    13	    <sdpi-item id="answer-row" label="Answer" style="display: none">
    14	      <input id="answer" type="text" />
    15	    </sdpi-item>
    16	
    17	    <div id="runlog-account"></div>
    18	    <script src="account.js"></script>
    19	    <script>
    20	      // The moves and presets are the pack's own words, so they come from the
    21	      // plugin on every appear rather than being listed here.
    22	      (() => {
    23	        const { streamDeckClient } = SDPIComponents;
    24	        const target = document.getElementById("target");
    25	        const answer = document.getElementById("answer");
    26	        const answerRow = document.getElementById("answer-row");
    27	        let current = null;
    28	
    29	        const option = (value, label) => {
    30	          const o = document.createElement("option");
    31	          o.value = JSON.stringify(value);
    32	          o.textContent = label;
    33	          return o;
    34	        };
    35	
    36	        const fill = (moves, presets) => {
    37	          target.replaceChildren(option(null, "Set up"), option({ kind: "roll" }, "The waiting roll"));
    38	          for (const m of moves) target.appendChild(option({ kind: "move", id: m.id }, m.label));
    39	          for (const p of presets) target.appendChild(option({ kind: "answer", preset: p.kind, value: "" }, p.label));
    40	          show();
    41	        };
    42	
    43	        const show = () => {
    44	          const chosen = current ? JSON.stringify(stripValue(current)) : "null";
    45	          const match = [...target.options].find((o) => o.value === chosen);
    46	          if (match) target.value = match.value;
    47	          const isAnswer = current?.kind === "answer";
    48	          answerRow.style.display = isAnswer ? "" : "none";
    49	          answer.value = isAnswer ? (current.value ?? "") : "";
    50	        };
    51	
    52	        // A preset option is identified by its kind; the value is typed beside it.
    53	        const stripValue = (t) => (t.kind === "answer" ? { kind: "answer", preset: t.preset, value: "" } : t);
    54	
    55	        const save = () => streamDeckClient.setSettings(current ? { target: current } : {});
    56	
    57	        target.addEventListener("change", () => {
    58	          current = JSON.parse(target.value);
    59	          show();
    60	          save();
    61	        });
    62	        answer.addEventListener("change", () => {
    63	          if (current?.kind !== "answer") return;
    64	          current = { ...current, value: answer.value };
    65	          save();
    66	        });
    67	
    68	        streamDeckClient.sendToPropertyInspector.subscribe(({ payload }) => {
    69	          if (payload?.t === "offer") fill(payload.moves ?? [], payload.presets ?? []);
    70	        });
    71	        void streamDeckClient.getSettings().then(({ settings }) => {
    72	          current = settings?.target ?? null;
    73	          show();
    74	        });
    75	        fill([], []);
    76	      })();
    77	    </script>
    78	  </body>
    79	</html>

