     3	 *
     4	 * Elgato wants PNG at two sizes for everything, and wants two different
     5	 * things from one glyph: the action list takes it white on nothing at 20
     6	 * square, and a key takes it in the app's colors on the app's ground at 72
     7	 * square. So each glyph is drawn once, in white, and the key image is that
     8	 * same glyph recolored and set on a ground here rather than drawn twice.
     9	 *
    10	 * `npm run icons -w streamdeck`. Nothing at run time depends on this; the
    11	 * rasterizer is a devDependency of the repository, not of the plugin.
    12	 */
    13	import { Resvg } from "@resvg/resvg-js";
    14	import { mkdirSync, readdirSync, readFileSync, writeFileSync } from "node:fs";
    15	import { dirname, join } from "node:path";
    16	import { fileURLToPath } from "node:url";
    17	
    18	const here = dirname(fileURLToPath(import.meta.url));
    19	const imgs = join(here, "..", "com.scrthq.runlog.sdPlugin", "imgs");
    20	
    21	/** The app's own: the ground, celadon, and kiln for the one key that takes something back. */
    22	const GROUND = "#151311";
    23	const ACCENT = "#9fd3b6";
    24	const WARN = "#e0a94f";
    25	
    26	/** Both sizes of one drawing, `@2x` being the second. */
    27	function write(svg, out, size) {
    28	  mkdirSync(dirname(out), { recursive: true });
    29	  for (const [suffix, w] of [
    30	    ["", size],
    31	    ["@2x", size * 2],
    32	  ]) {
