167	    // The full label, unwrapped, so a tooltip (or a test) sees the whole
168	    // thing even when the drawn lines above cut it short.
169	    `<title>${esc(face.title)}</title>` +
170	    `<rect width="144" height="144" rx="14" fill="${t.ground}"/>` +
171	    `<rect x="3" y="3" width="138" height="138" rx="12" fill="none" stroke="${t.edge}" stroke-width="3"/>` +
172	    spans +
173	    when +
174	    `</svg>`;
175	  return `data:image/svg+xml;base64,${Buffer.from(svg, "utf8").toString("base64")}`;
176	}

