 1	import { beforeEach, afterEach, describe, expect, it, vi } from "vitest";
 2	
 3	import { initial, reduce, type DeckState, type Offer } from "../state.ts";
 4	
 5	// `next.ts` reaches the store through `../plugin.ts`, which registers every
 6	// action and opens a wire. The press is the only thing under test, so the
 7	// module is stood in for: one state to read, one press to record.
 8	const mock = vi.hoisted(() => ({ state: null as unknown as DeckState, pressed: [] as unknown[] }));
 9	vi.mock("../plugin.ts", () => ({
10	  store: {
11	    get state() {
12	      return mock.state;
13	    },
14	    dispatch: () => {},
15	    subscribe: () => () => {},
16	  },
17	  sayWho: async () => {},
18	  wire: {
19	    press: (p: unknown) => {
20	      mock.pressed.push(p);
21	      return "r1";
22	    },
23	  },
24	}));
25	
26	const { Next } = await import("./next.ts");
27	
28	const T = 1_000_000;
29	const offer: Offer = {
30	  seq: 42,
31	  primary: null,
32	  moves: [],
33	  undo: null,
34	  needsPage: "Tick the list on the page",
35	  presets: [],
36	  setups: [],
37	};
38	
39	/** A deck signed in, connected, following one run, on the step this offer describes. */
40	const on = (presets: Offer["presets"]): DeckState => {
41	  let s = reduce(initial(), { t: "session", state: "ok" }, T);
42	  s = reduce(s, { t: "on", on: true }, T);
43	  s = reduce(s, { t: "socket", state: "open" }, T);
44	  s = reduce(s, { t: "runs", runs: [{ id: "s1", name: "Thursday" }], any: true }, T);
45	  return reduce(s, { t: "snapshot", snapshot: { offer: { ...offer, presets } } }, T);
46	};
47	
48	const key = () => ({
49	  id: "a1",
50	  isKey: () => true,
51	  isDial: () => false,
52	  showAlert: async () => {},
53	  showOk: async () => {},
54	});
55	
56	describe("pressing the follow key", () => {
57	  beforeEach(() => {
58	    vi.useFakeTimers();
59	    mock.pressed = [];
60	  });
61	  afterEach(() => vi.useRealTimers());
62	
63	  it("takes the checklist the page is offering", async () => {
64	    mock.state = on([{ kind: "checklist", label: "Tick everything and Next", items: 2 }]);
65	    await new Next().onKeyDown({ action: key(), payload: { settings: {} } } as never);
66	    expect(mock.pressed).toEqual([{ press: "answer", answer: { ticks: "all" } }]);
67	  });
68	
69	  it("takes the first suggestion from a dial as well as a key", async () => {
70	    mock.state = on([{ kind: "declareSubject", label: "Name what you are going for", suggestions: ["A tall bowl"] }]);
71	    await new Next().onDialDown({ action: key(), payload: { settings: {} } } as never);
72	    expect(mock.pressed).toEqual([{ press: "answer", answer: { subject: "A tall bowl" } }]);
73	  });
74	
75	  it("takes the same decision from a touch tap as from the dial under it", async () => {
76	    mock.state = on([{ kind: "checklist", label: "Tick everything and Next", items: 2 }]);
77	    await new Next().onTouchTap({ action: key(), payload: { settings: {} } } as never);
78	    expect(mock.pressed).toEqual([{ press: "answer", answer: { ticks: "all" } }]);
79	  });
80	
81	  it("presses the primary and lets the page refuse it where it was told to stop", async () => {
82	    mock.state = on([{ kind: "checklist", label: "Tick everything and Next", items: 2 }]);
83	    await new Next().onKeyDown({ action: key(), payload: { settings: { stop: true } } } as never);
84	    expect(mock.pressed).toEqual([{ press: "primary" }]);
85	  });
86	});

